def cached_call_cost(prefix_tokens: int, new_tokens: int, rate_per_million: float) -> float:
    """Cost of one cached-prefix API call: prefix tokens at 0.1x, new tokens at full rate."""
    billed_tokens = prefix_tokens * 0.1 + new_tokens
    cost = billed_tokens * rate_per_million / 1_000_000
    return round(cost, 5)

print(cached_call_cost(20000, 50, 3.0))

def cache_savings_percent(prefix_tokens: int, new_tokens: int, rate_per_million: float) -> float:
    """Percent saved on one call when the prefix is a cache hit vs. no caching at all."""
    no_cache_cost = (prefix_tokens + new_tokens) * rate_per_million / 1_000_000
    cached_cost = (prefix_tokens * 0.1 + new_tokens) * rate_per_million / 1_000_000
    return round((1 - cached_cost / no_cache_cost) * 100, 1)

print(cache_savings_percent(20000, 50, 3.0))
